import{_ as n,a0 as c,w as r,s,ao as a,I as l,x as o,a1 as t,A as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"你必須瞭解的基礎的 Linux 網絡命令 | LCTT x X-CMD","titleTemplate":false,"description":"你必須瞭解的基礎的 Linux 網絡命令 | LCTT (201609) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"你必須瞭解的基礎的 Linux 網絡命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"你必須瞭解的基礎的 Linux 網絡命令 | LCTT (201609) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201609/20160621 Basic Linux Networking Commands You Should Know","title":"你必須瞭解的基礎的 Linux 網絡命令","tag":"201609","desc":""},"relativePath":"201609/20160621 Basic Linux Networking Commands You Should Know.md","filePath":"[post].md"}'),u={name:"201609/20160621 Basic Linux Networking Commands You Should Know.md"};function p(m,e,P,f,h,g){const i=c("Link");return r(),s("div",null,[e[21]||(e[21]=a('<h1 id="你必須瞭解的基礎的-linux-網絡命令" tabindex="-1">你必須瞭解的基礎的 Linux 網絡命令 <a class="header-anchor" href="#你必須瞭解的基礎的-linux-網絡命令" aria-label="Permalink to “你必須瞭解的基礎的 Linux 網絡命令”">​</a></h1><p><img src="https://itsfoss.com/wp-content/uploads/2016/06/Basic-Networking-Commands-Linux.jpg" alt=""></p><blockquote><p>摘要：有抱負的 Linux 系統管理員和 Linux 狂熱者必須知道的、最重要的、而且基礎的 Linux 網絡命令合集。</p></blockquote><p>在 It’s FOSS 我們並非每天都談論 Linux 的“命令列方面”。基本上，我更專注於 Linux 的桌面端。但你們讀者中的一些人在內部調查（僅面向 It&#39;s FOSS newsletter 訂閲者）中指出，你們也想學些命令列技巧。速查表也受大部分讀者所喜歡和支持。</p><p>為此，我編輯了一個 Linux 中基礎網絡命令的列表。它並不是一個教你如何使用這些命令的教程，而是一個命令合集和他們的簡短解釋。所以，如果你已經使用過這些命令，你可以用它來快速記住命令。</p><p>你可以把這個網頁添加為書籤以便快速查閲，或輸出一個 PDF 版本以便離線使用。</p><p>當我還是通信系統工程專業的學生的時候我就有這個 Linux 網絡命令的列表了。它幫助我在計算機網絡課程獲得了高分。希望它也能以同樣的方式幫助你。</p><h3 id="linux-基礎網絡命令列表" tabindex="-1">Linux 基礎網絡命令列表 <a class="header-anchor" href="#linux-基礎網絡命令列表" aria-label="Permalink to “Linux 基礎網絡命令列表”">​</a></h3><p>我在計算機網絡課程上使用 FreeBSD，不過這些 UNIX 命令應該也能在 Linux 上同樣工作。</p><h4 id="連通性" tabindex="-1">連通性 <a class="header-anchor" href="#連通性" aria-label="Permalink to “連通性”">​</a></h4>',10)),l("ul",null,[e[7]||(e[7]=l("li",null,[l("code",null,"ping <host>"),o("：發送 ICMP echo 消息（一個包）到主機。這可能會不停地發送直到你按下 "),l("code",null,"Control-C"),o("。Ping 的通意味着一個包從你的機器通過 ICMP 發送出去，並在 IP 層回顯。Ping 告訴你另一個主機是否在運行。")],-1)),l("li",null,[e[5]||(e[5]=l("code",null,"telnet <host> [port]",-1)),e[6]||(e[6]=o("：與主機在指定的端口通信。默認的 telnet 端口是 23。按 Control-] 以退出 telnet。其它一些常用的端口是： ",-1)),l("ul",null,[e[3]||(e[3]=l("li",null,"7 —— echo 端口",-1)),e[4]||(e[4]=l("li",null,"25 —— SMTP，用於發送郵件",-1)),l("li",null,[e[1]||(e[1]=o("79 —— Finger (LCTT 譯註：",-1)),t(i,{href:"https://en.wikipedia.org/wiki/Finger_protocol"},{default:d(()=>[...e[0]||(e[0]=[o("維基百科 - Finger protocal",-1)])]),_:1}),e[2]||(e[2]=o("，不過舉例 Finger 恐怕不合時宜，倒不如試試 80？），提供該網絡下其它用户的信息。",-1))])])])]),e[22]||(e[22]=a('<h4 id="arp" tabindex="-1">ARP <a class="header-anchor" href="#arp" aria-label="Permalink to “ARP”">​</a></h4><p>ARP 用於將 IP 地址轉換為以太網地址。root 用户可以添加和刪除 ARP 記錄。當 ARP 記錄被污染或者錯誤時，刪除它們會有用。root 顯式添加的 ARP 記錄是永久的 —— 代理設置的也是。ARP 表保存在內核中，動態地被操作。ARP 記錄會被緩存，通常在 20 分鐘後失效並被刪除。</p><ul><li><code>arp -a</code>：打印 ARP 表。</li><li><code>arp -s &lt;ip_address&gt; &lt;mac_address&gt; [pub]</code>：添加一條記錄到表中。</li><li><code>arp -a -d</code>：刪除 ARP 表中的所有記錄。</li></ul><h4 id="路由" tabindex="-1">路由 <a class="header-anchor" href="#路由" aria-label="Permalink to “路由”">​</a></h4><ul><li><code>netstat -r</code>：打印路由表。路由表保存在內核中，用於 IP 層把包路由到非本地網絡。</li><li><code>route add</code>：route 命令用於向路由表添加靜態（手動指定而非動態）路由路徑。所有從該 PC 到那個 IP/子網的流量都會經由指定的網關 IP。它也可以用來設置一個默認路由。例如，在 IP/子網處使用 0.0.0.0，就可以發送所有包到特定的網關。</li><li><code>routed</code>：控制動態路由的 BSD 守護程序。開機時啓動。它運行 RIP 路由協議。只有 root 用户可用。沒有 root 權限你不能運行它。</li><li><code>gated</code>：gated 是另一個使用 RIP 協議的路由守護進程。它同時支持 OSPF、EGP 和 RIP 協議。只有 root 用户可用。</li><li><code>traceroute</code>：用於跟蹤 IP 包的路由。它每次發送包時都把跳數加 1，從而使得從源地址到目的地之間的所有網關都會返回消息。</li><li><code>netstat -rnf inet</code>：顯示 IPv4 的路由表。</li><li><code>sysctl net.inet.ip.forwarding=1</code>：啓用包轉發（把主機變為路由器）。</li><li><code>route add|delete [-net|-host] &lt;destination&gt; &lt;gateway&gt;</code>：（如 <code>route add 192.168.20.0/24 192.168.30.4</code>）添加一條路由。</li><li><code>route flush</code>：刪除所有路由。</li><li><code>route add -net 0.0.0.0 192.168.10.2</code>：添加一條默認路由。</li><li><code>routed -Pripv2 -Pno_rdisc -d [-s|-q]</code>：運行 routed 守護進程，使用 RIPv2 協議，不啓用 ICMP 自動發現，在前台運行，供給模式或安靜模式。</li><li><code>route add 224.0.0.0/4 127.0.0.1</code>：為本地地址定義多播路由。（LCTT 譯註：原文存疑）</li><li><code>rtquery -n &lt;host&gt;</code>（LCTT 譯註：增加了 host 參數）：查詢指定主機上的 RIP 守護進程（手動更新路由表）。</li></ul><h4 id="其它" tabindex="-1">其它 <a class="header-anchor" href="#其它" aria-label="Permalink to “其它”">​</a></h4><ul><li><code>nslookup</code>：向 DNS 服務器查詢，將 IP 轉為名稱，或反之。例如，<code>nslookup facebook.com</code> 會給出 facebook.com 的 IP。</li><li><code>ftp &lt;host&gt; [port]</code>（LCTT 譯註：原文中 water 應是筆誤）：傳輸文件到指定主機。通常可以使用 登錄名 &quot;anonymous&quot; , 密碼 &quot;guest&quot; 來登錄。</li><li><code>rlogin -l &lt;host&gt;</code>（LCTT 譯註：添加了 host 參數）：使用類似 telnet 的虛擬終端登錄到主機。</li></ul><h4 id="重要文件" tabindex="-1">重要文件 <a class="header-anchor" href="#重要文件" aria-label="Permalink to “重要文件”">​</a></h4><ul><li><code>/etc/hosts</code>：域名到 IP 地址的映射。</li><li><code>/etc/networks</code>：網絡名稱到 IP 地址的映射。</li><li><code>/etc/protocols</code>：協議名稱到協議編號的映射。</li><li><code>/etc/services</code>：TCP/UDP 服務名稱到端口號的映射。</li></ul><h4 id="工具和網絡性能分析" tabindex="-1">工具和網絡性能分析 <a class="header-anchor" href="#工具和網絡性能分析" aria-label="Permalink to “工具和網絡性能分析”">​</a></h4><ul><li><code>ifconfig &lt;interface&gt; &lt;address&gt; [up]</code>：啓動接口。</li><li><code>ifconfig &lt;interface&gt; [down|delete]</code>：停止接口。</li><li><code>ethereal &amp;</code>：在後台打開 <code>ethereal</code> 而非前台。</li><li><code>tcpdump -i -vvv</code>：抓取和分析包的工具。</li><li><code>netstat -w [seconds] -I [interface]</code>：顯示網絡設置和統計信息。</li><li><code>udpmt -p [port] -s [bytes] target_host</code>：發送 UDP 流量。</li><li><code>udptarget -p [port]</code>：接收 UDP 流量。</li><li><code>tcpmt -p [port] -s [bytes] target_host</code>：發送 TCP 流量。</li><li><code>tcptarget -p [port]</code>：接收 TCP 流量。</li></ul><h4 id="交換機" tabindex="-1">交換機 <a class="header-anchor" href="#交換機" aria-label="Permalink to “交換機”">​</a></h4><ul><li><code>ifconfig sl0 srcIP dstIP</code>：配置一個串行接口（在此前先執行 <code>slattach -l /dev/ttyd0</code>，此後執行 <code>sysctl net.inet.ip.forwarding=1</code>）</li><li><code>telnet 192.168.0.254</code>：從子網中的一台主機訪問交換機。</li><li><code>sh ru</code> 或 <code>show running-configuration</code>：查看當前配置。</li><li><code>configure terminal</code>：進入配置模式。</li><li><code>exit</code>：退出當前模式。（LCTT 譯註：原文存疑）</li></ul><h4 id="vlan" tabindex="-1">VLAN <a class="header-anchor" href="#vlan" aria-label="Permalink to “VLAN”">​</a></h4><ul><li><code>vlan n</code>：創建一個 ID 為 n 的 VLAN。</li><li><code>no vlan N</code>：刪除 ID 為 n 的 VLAN。</li><li><code>untagged Y</code>：添加端口 Y 到 VLAN n。</li><li><code>ifconfig vlan0 create</code>：創建 vlan0 接口。</li><li><code>ifconfig vlan0 vlan_ID vlandev em0</code>：把 em0 加入到 vlan0 接口（LCTT 譯註：原文存疑），並設置標記為 ID。</li><li><code>ifconfig vlan0 [up]</code>：啓用虛擬接口。</li><li><code>tagged Y</code>：為當前 VLAN 的端口 Y 添加標記幀支持。</li></ul><h4 id="udp-tcp" tabindex="-1">UDP/TCP <a class="header-anchor" href="#udp-tcp" aria-label="Permalink to “UDP/TCP”">​</a></h4><ul><li><code>socklab udp</code>：使用 UDP 協議運行 <code>socklab</code>。</li><li><code>sock</code>：創建一個 UDP 套接字，等效於輸入 <code>sock udp</code> 和 <code>bind</code>。</li><li><code>sendto &lt;Socket ID&gt; &lt;hostname&gt; &lt;port #&gt;</code>：發送數據包。</li><li><code>recvfrom &lt;Socket ID&gt; &lt;byte #&gt;</code>：從套接字接收數據。</li><li><code>socklab tcp</code>：使用 TCP 協議運行 <code>socklab</code>。</li><li><code>passive</code>：創建一個被動模式的套接字，等效於 <code>socklab</code>，<code>sock tcp</code>，<code>bind</code>，<code>listen</code>。</li><li><code>accept</code>：接受進來的連接（可以在發起進來的連接之前或之後執行）。</li><li><code>connect &lt;hostname&gt; &lt;port #&gt;</code>：等效於 <code>socklab</code>，<code>sock tcp</code>，<code>bind</code>，<code>connect</code>。</li><li><code>close</code>：關閉連接。</li><li><code>read &lt;byte #&gt;</code>：從套接字中讀取 n 字節。</li><li><code>write</code>：（例如，<code>write ciao</code>、<code>write #10</code>）向套接字寫入 &quot;ciao&quot; 或 10 個字節。</li></ul><h4 id="nat-防火牆" tabindex="-1">NAT/防火牆 <a class="header-anchor" href="#nat-防火牆" aria-label="Permalink to “NAT/防火牆”">​</a></h4><ul><li><code>rm /etc/resolv.conf</code>：禁止地址解析，保證你的過濾和防火牆規則正確工作。</li><li><code>ipnat -f file_name</code>：將過濾規則寫入文件。</li><li><code>ipnat -l</code>：顯示活動的規則列表。</li><li><code>ipnat -C -F</code>：重新初始化規則表。</li><li><code>map em0 192.168.1.0/24 -&gt; 195.221.227.57/32 em0</code>：將 IP 地址映射到接口。</li><li><code>map em0 192.168.1.0/24 -&gt; 195.221.227.57/32 portmap tcp/udp 20000:50000</code>：帶端口號的映射。</li><li><code>ipf -f file_name</code>：將過濾規則寫入文件。</li><li><code>ipf -F -a</code>：重置規則表。</li><li><code>ipfstat -I</code>：當與 -s 選項合用時列出活動的狀態條目（LCTT 譯註：原文存疑）。</li></ul><p>希望這份基礎的 Linux 網絡命令合集對你有用。歡迎各種問題和建議。</p><hr>',21)),l("p",null,[e[9]||(e[9]=o("via: ",-1)),t(i,{href:"https://itsfoss.com/basic-linux-networking-commands"},{default:d(()=>[...e[8]||(e[8]=[o("https://itsfoss.com/basic-linux-networking-commands",-1)])]),_:1})]),l("p",null,[e[13]||(e[13]=o("作者：",-1)),t(i,{href:"https://itsfoss.com/author/abhishek/"},{default:d(()=>[...e[10]||(e[10]=[o("Abhishek Prakash",-1)])]),_:1}),e[14]||(e[14]=o(" 譯者：",-1)),t(i,{href:"https://github.com/bianjp"},{default:d(()=>[...e[11]||(e[11]=[o("bianjp",-1)])]),_:1}),e[15]||(e[15]=o(" 校對：",-1)),t(i,{href:"https://github.com/wxy"},{default:d(()=>[...e[12]||(e[12]=[o("wxy",-1)])]),_:1})]),l("p",null,[e[18]||(e[18]=o("本文由 ",-1)),t(i,{href:"https://github.com/LCTT/TranslateProject"},{default:d(()=>[...e[16]||(e[16]=[o("LCTT",-1)])]),_:1}),e[19]||(e[19]=o(" 原創編譯，",-1)),t(i,{href:"https://linux.cn/"},{default:d(()=>[...e[17]||(e[17]=[o("Linux中國",-1)])]),_:1}),e[20]||(e[20]=o(" 榮譽推出",-1))])])}const k=n(u,[["render",p]]);export{b as __pageData,k as default};
